use verus::prelude::*;

//----------------------------------------------------------------
// Spec‐level definitions of the two fixed character sets.
//
// We define two little boolean predicates is_set_a / is_set_b
// that hold exactly on the fifteen letters in A or the eleven
// letters in B, respectively.
