#[spec]
fn is_set_a(c: char) -> bool {
    c == 'A' || c == 'E' || c == 'F' ||
    c == 'H' || c == 'I' || c == 'K' ||
    c == 'L' || c == 'M' || c == 'N' ||
    c == 'T' || c == 'V' || c == 'W' ||
    c == 'X' || c == 'Y' || c == 'Z'
}

#[spec]
fn is_set_b(c: char) -> bool {
    c == 'B' || c == 'C' || c == 'D' ||
    c == 'G' || c == 'J' || c == 'O' ||
    c == 'P' || c == 'Q' || c == 'R' ||
    c == 'S' || c == 'U'
}

//----------------------------------------------------------------
// solve: checks whether all the characters of `word` lie in
// one of the two fixed sets.  If so, returns ['Y','E','S'],
// otherwise returns ['N','O'].
//
// Specification:
//
//   Ensures that it returns YES exactly when
//     (forall i < word.len(): is_set_a(word[i]))
//     OR
//     (forall i < word.len(): is_set_b(word[i]))
//   and returns NO exactly otherwise.
//----------------------------------------------------------------

#[requires(true)]
#[ensures(
    // ⇔ YES ↔ (all in A ∨ all in B)
    result == vec!['Y','E','S'] <==>
      (
        (forall |i: usize| i < word.len() ==> is_set_a(word[i]))
        ||
        (forall |i: usize| i < word.len() ==> is_set_b(word[i]))
      ),
    // ⇔ NO ↔ ¬(all in A ∨ all in B)
    result == vec!['N','O'] <==>
      !(
        (forall |i: usize| i < word.len() ==> is_set_a(word[i]))
        ||
        (forall |i: usize| i < word.len() ==> is_set_b(word[i]))
      )
)]
pub fn solve(word: Vec<char>) -> Vec<char> {
    // Define the two fixed sets of letters.
    const SET_A: [char; 15] = [
        'A', 'E', 'F', 'H', 'I', 'K', 'L', 'M', 'N', 'T', 'V', 'W', 'X', 'Y', 'Z',
    ];
    const SET_B: [char; 11] = [
        'B', 'C', 'D', 'G', 'J', 'O', 'P', 'Q', 'R', 'S', 'U',
    ];

    // Check if all characters belong to SET_A
    let all_in_a = word.iter().all(|c| SET_A.contains(c));
    // Check if all characters belong to SET_B
    let all_in_b = word.iter().all(|c| SET_B.contains(c));

    // Return "YES" if the word is entirely in one set, otherwise "NO"
    if all_in_a || all_in_b {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

